guidedExercise.solutionCode:
def schedule(replicas, request_gib, allocatable_gib):
    if replicas < 0 or request_gib <= 0 or allocatable_gib < 0:
        raise ValueError('invalid scheduling inputs')
    scheduled = min(replicas, int(allocatable_gib // request_gib))
    return {'scheduled': scheduled, 'pending': replicas - scheduled}

def startup_ready(load_seconds, startup_budget_seconds):
    if load_seconds < 0 or startup_budget_seconds <= 0:
        raise ValueError('invalid startup timing')
    return load_seconds <= startup_budget_seconds

